// nl — Nederlands.
//
// A chave é o TEXTO EM PORTUGUÊS, exatamente como aparece no código. O que faltar aqui aparece em
// português, e não como tela vazia.
//
// TOM: **je/jij**, nunca *u*. É a mesma escolha do alemão (du) e do italiano (tu), e no neerlandês ela
// é ainda mais visível: "u" num app de amigos soa como carta do banco ou da prefeitura.
//
// VOCABULÁRIO, decidido uma vez: comunidade = community (é como se diz em neerlandês de verdade;
// "gemeenschap" soa a paróquia), canal = kanaal, sala de voz = spraakkamer, tópico = draadje,
// transmissão = uitzending, lixeira = prullenbak, selo = zegel, insígnia = insigne.
//
// UMA ARMADILHA QUE QUASE PEGOU: "Meldingen" serve tanto para NOTIFICAÇÕES quanto para DENÚNCIAS, e
// as duas telas existem no Syden. Ficou Notificações = "Notificaties" e Denúncias = "Meldingen" — as
// duas palavras são naturais, e assim nenhum menu aponta para o lugar errado.

