  'Uma por linha. Vale a palavra inteira, sem diferença de acento ou de maiúscula: proibir uma palavra não barra outra mais longa que só a contenha.': 'Eén per regel. Het hele woord telt, zonder verschil in accenten of hoofdletters: een woord verbieden blokkeert geen langer woord dat het alleen bevat.',
