  'O selo aparece aqui quando o primeiro marco cair. Até lá ele fica guardado — e chegar nele é justamente o que ele vai significar.': 'De badge verschijnt hier als de eerste mijlpaal valt. Tot die tijd blijft hij liggen — en hem halen is precies wat hij gaat betekenen.',
