  'Serve para recuperar a senha e para avisar você se algo acontecer com o Syden. Sem e-mail, uma senha esquecida não tem volta.': 'Het haalt je wachtwoord terug en waarschuwt je als er iets met Syden gebeurt. Zonder e-mail heeft een vergeten wachtwoord geen weg terug.',
