  'Você ainda não tem nenhuma. Elas chegam como presente ou como recompensa — por exemplo, quando uma ideia sua entra no Syden.': 'Je hebt er nog geen. Ze komen als cadeau of als beloning — bijvoorbeeld als een idee van jou in Syden terechtkomt.',
  'Você entrou por um serviço de fora e ainda não tem senha nesta conta. Defina uma aqui: passa a valer como segundo jeito de entrar, e é o que permite desligar aquele serviço depois.': 'Je bent binnengekomen via een dienst van buitenaf en hebt nog geen wachtwoord op dit account. Stel er hier een in: het wordt een tweede manier om binnen te komen, en het is wat je later toelaat die dienst los te koppelen.',
  'Você perde o acesso aos canais desta comunidade. Para voltar, vai precisar de um convite novo.': 'Je verliest de toegang tot de kanalen van deze community. Om terug te komen heb je een nieuwe uitnodiging nodig.',
