  'Os marcos abaixo foram escolhidos para não haver como alcançá-los sozinho — todos precisam de mais de uma pessoa, ao longo do tempo.': 'De mijlpalen hieronder zijn zo gekozen dat je ze niet alleen kunt halen — elke mijlpaal heeft meer dan één persoon nodig, over tijd.',
