  '{tipo} «{item}» ({onde}) saiu do Syden porque {quem} disse ter os direitos. Se você tinha autorização para publicar, responda aqui contando: a sua resposta vai ser levada em conta. Enquanto isso não ficar claro, fica fora. Os termos explicam como funciona, na seção 4: https://syden.chat/termos.html#direito-autoral': '{tipo} «{item}» ({onde}) is van Syden gehaald omdat {quem} zegt de rechten te hebben. Had je toestemming om het te publiceren? Antwoord dan hier en leg het uit: je antwoord wordt meegenomen. Zolang dat niet duidelijk is, blijft het offline. De voorwaarden leggen in sectie 4 uit hoe het werkt: https://syden.chat/termos.html#direito-autoral',
