  'Cinco rodadas de jogos rápidos, cada um na própria tela: reflexo, pontaria, memória e olho. Quem for melhor em cada rodada ganha mais pontos.': 'Vijf rondes snelle spelletjes, iedereen op het eigen scherm: reflexen, mikken, geheugen en oplettendheid. Wie in elke ronde het best is, krijgt meer punten.',
  'Saque rápido': 'Snel trekken',
