  'A subida não está andando.': 'De klim is niet bezig.',
  'A tábua racha quando alguém para em cima. Continue andando e empurre os outros para a água!': 'De plank barst als iemand erop blijft staan. Blijf bewegen en duw de anderen het water in!',
  'A torre do celeiro': 'De schuurtoren',
