  'A turma caiu.': 'De groep is gevallen.',
  'A turma inteira contra a toupeira-rei, que sai das tocas em três fases. Fuja das marcas no chão, pegue os torrões azulados e atire de volta. Ganha a turma, ou ninguém.': 'De hele groep tegen de mollenkoning, die in drie fasen uit de holen komt. Ontwijk de markeringen op de grond, pak de blauwige kluiten en gooi ze terug. De groep wint, of niemand.',
  'Abóboras ladeira abaixo': 'Pompoenen bergaf',
  'Acerte os corvos que passarem. No coelhinho, não!': 'Raak de kraaien die voorbijkomen. Niet het konijntje!',
  'Acertos: {n}': 'Treffers: {n}',
  'Afofa a terra': 'Maakt de grond los',
  'Água e sol': 'Water en zon',
  'Alterne ← e → no ritmo. Com pressa demais, o fôlego acaba.': 'Wissel ← en → af op het ritme. Te veel haast en je bent buiten adem.',
  'Ao calendário': 'Naar de kalender',
  'Ao guarda-roupa': 'Naar de kledingkast',
  'Aperte a seta que aparecer para puxar a corda. Errar trava!': 'Druk op de pijl die verschijnt om aan het touw te trekken. Fout drukken blokkeert je!',
  'Aperte para a roda frear. Ela sempre desliza um pouco antes de parar.': 'Druk om het rad te remmen. Het glijdt altijd nog een stukje door.',
  'Aperte sem parar para nadar. Quando vier um tronco, mergulhe!': 'Blijf drukken om te zwemmen. Komt er een boomstam, duik!',
  'Armadura': 'Een harnas',
