  'Bata nas lagartas que saírem das tocas. No coelhinho, não!': 'Mep de rupsen die uit de holen komen. Niet het konijntje!',
  'Bata quando aparecer a flor igual à do quadrinho. Na figura errada, está fora.': 'Mep wanneer de bloem uit het kadertje verschijnt. Bij de verkeerde figuur lig je eruit.',
  'Batata': 'Aardappel',
