  'Bombeie quando o anel acender. Fora do ritmo, o ar escapa.': 'Pomp als de ring oplicht. Uit de maat ontsnapt de lucht.',
  'Brasas da fogueira': 'Kampvuursintels',
  'Cabo de guerra': 'Touwtrekken',
  'Cada um rema de um lado: a remada empurra a balsa para o outro. Juntos, ela vai para a frente. Peguem as cenouras!': 'Ieder peddelt aan één kant: een slag duwt het vlot naar de andere kant. Samen gaat het vooruit. Pak de wortels!',
  'Caiu! Agora é torcer de longe.': 'Neergeschoten! Nu is het van ver aanmoedigen.',
  'Canteiro que encolhe': 'Krimpend bed',
  'Cartas do celeiro': 'Schuurkaarten',
  'Celeiro': 'Schuur',
  'Cenoura teleguiada': 'Geleide wortel',
  'Cenouras': 'Wortels',
  'Chão que desmorona': 'Instortende vloer',
  'Chuva de cenouras': 'Wortelregen',
  'Cinco': 'Vijf',
  'Coelhos em teco-tecos sobre a horta, atirando ervilhas e uma cenoura teleguiada de cada vez. Dois acertos dá para aguentar; o terceiro derruba. O último no ar ganha.': 'Konijnen in vliegtuigjes boven de moestuin, met erwten en telkens één geleide wortel. Twee treffers hou je vol; de derde haalt je neer. Wie als laatste in de lucht is, wint.',
  'Colheita em dupla': 'Oogsten met z\'n tweeën',
  'Coma a torta com a sua dupla, alternando ◀ e ▶. Quem acabar primeiro ganha!': 'Eet de taart op met je duo, met ◀ en ▶ om de beurt. Wie het eerst klaar is, wint!',
  'Come as folhas': 'Eet de bladeren',
  'Corrida de barquinhos no lago, no riacho e no mangue. A água desliza: tire o pé antes da curva, cuidado com a margem e aproveite a correnteza e as argolas. No Solo, contra o relógio e os fantasmas dos amigos.': 'Bootjesraces op het meer, de beek en in de mangrove. Het water glijdt: gas los voor de bocht, let op de oever en gebruik de stroming en de ringen. In Solo tegen de klok en de geesten van je vrienden.',
  'Corrida de cavalinho': 'Stokpaardrace',
  'Dano da turma: {n}': 'Schade van de groep: {n}',
  'De galho em galho': 'Van tak naar tak',
  'De que cor é a folha da cenoura?': 'Welke kleur heeft het loof van een wortel?',
  'Desça pegando as cenouras. Das pedras, fuja!': 'Ga naar beneden en pak de wortels. Ontwijk de stenen!',
  'Descubra quem está escondido. Uma chance só: quanto antes, mais vale.': 'Ontdek wie zich verstopt. Eén kans: hoe eerder, hoe meer het waard is.',
  'Destampe os potes': 'Open de potten',
  'Desvie das brasas. São só três corações!': 'Ontwijk de sintels. Maar drie hartjes!',
  'Dez': 'Tien',
  'Do que uma planta precisa para crescer?': 'Wat heeft een plant nodig om te groeien?',
  'Dois acertos você aguenta; o terceiro derruba. Curva fechada perto da cerca protege por um instante.': 'Twee treffers hou je vol; de derde haalt je neer. Een krappe bocht bij het hek beschermt je even.',
  'Duas': 'Twee',
  'Duelo de aviõezinhos': 'Papieren-vliegtuigjesduel',
  'Em dupla: quem está no galho solta os morangos maduros, e quem está embaixo apanha com a cesta.': 'Met z\'n tweeën: wie op de tak zit laat de rijpe aardbeien vallen, en wie beneden staat vangt ze met de mand.',
  'Em que dia é o aniversário do Syden?': 'Op welke dag is Syden jarig?',
  'Empurre os outros para fora do canteiro. A borda que pisca vai cair!': 'Duw de anderen van het bed af. De knipperende rand valt zo!',
  'Encurrale a galinha. Cansada, ela fica lenta.': 'Drijf de kip in het nauw. Moe wordt ze traag.',
  'Escolha a resposta certa antes que o tempo acabe.': 'Kies het goede antwoord voordat de tijd om is.',
  'Escolher a torre': 'Toren kiezen',
  'Esconda-se onde a lanterna não vai olhar. Quem tem a lanterna procura!': 'Verstop je waar de lantaarn niet gaat kijken. Wie de lantaarn heeft, zoekt!',
  'Esconde-esconde na horta': 'Verstoppertje in de moestuin',
  'Espanta a chuva': 'Jaagt de regen weg',
  'Esta subida já tinha começado quando você abriu: você assiste.': 'Deze klim was al begonnen toen je hem opende: je kijkt mee.',
  'Fase {n} de {total}': 'Fase {n} van {total}',
  'Foguete de cenoura': 'Wortelraket',
  'Frear': 'Remmen',
  'Fuga do rio': 'Rivierontsnapping',
  'Fuja das marcas no chão. Passe por cima de um torrão azulado para pegá-lo e atire de volta na toupeira; a bomba de semente é uma por fase.': 'Ontwijk de markeringen op de grond. Loop over een blauwige kluit om hem op te pakken en gooi hem terug naar de mol; één zaadbom per fase.',
  'Gire cada tampa para o lado da seta, depressa. O lado errado aperta de novo.': 'Draai elk deksel snel de kant van de pijl op. De verkeerde kant draait hem weer vast.',
  'Guarde a ordem da dança. No fim, diga quem dançou na lâmpada marcada.': 'Onthoud de volgorde van de dans. Zeg aan het eind wie op de gemarkeerde lamp danste.',
  'Guarde onde fica cada pote e ponha todos de volta no lugar.': 'Onthoud waar elke pot staat en zet ze allemaal terug op hun plek.',
  'Lá de cima rolam abóboras; quem sobe troca de faixa para fugir delas!': 'Van boven rollen pompoenen; wie klimt, wisselt van baan om ze te ontwijken!',
  'Lagarta': 'Rups',
  'Lago da horta': 'Moestuinmeer',
  'Leite e mel': 'Melk en honing',
  'Lesma': 'Naaktslak',
