  'Pegue as cenouras no gelo e fuja dos repolhos.': 'Pak de wortels op het ijs en ontwijk de kolen.',
  'Pegue uma cenoura dourada e leve até a porteira. Falta uma: empurre quem estiver carregando!': 'Pak een gouden wortel en breng hem naar het hek. Er ontbreekt er één: duw wie er een draagt!',
