  'Siga os bichos de toca em toca. No fim, aponte onde está o do balão.': 'Volg de beestjes van hol naar hol. Wijs aan het eind aan waar dat met de ballon is.',
  'Silo': 'Silo',
  'Solte o cipó quando ele estiver na faixa clara.': 'Laat de liaan los als hij in de lichte strook is.',
  'Solte quando o nabo apontar para o campo. Girando mais rápido, vai mais longe.': 'Laat los als de raap naar het veld wijst. Hoe sneller hij draait, hoe verder hij vliegt.',
  'Suba até o cata-vento. O que cai e os corvos levam de volta ao último andar.': 'Klim naar de windwijzer. Vallen en de kraaien brengen je terug naar de laatste verdieping.',
  'Suba o celeiro por tábuas, fardos e vigas que se mexem até o cata-vento lá no alto, desviando das ferramentas que caem e dos corvos. No Solo, contra o relógio e os fantasmas dos amigos.': 'Klim de schuur op via planken, balen en bewegende balken tot de windwijzer bovenin, en ontwijk vallend gereedschap en kraaien. In Solo tegen de klok en de geesten van je vrienden.',
