  'A energia é a vida e o turbo: bater na borda gasta, a faixa cor-de-rosa recarrega.': 'Energie is je leven en je turbo: de rand raken kost energie, de roze strook laadt bij.',
  'A nave explodiu: a energia acabou.': 'Het schip is ontploft: de energie is op.',
  'Posição: {posicao} de {total}': 'Positie: {posicao} van {total}',
  'Escolher a pista': 'Kies de baan',
  'Corrida de naves-cenoura numa pista suspensa, muito mais rápida que o kart. A energia é a vida e o turbo: bater na borda gasta, a faixa cor-de-rosa recarrega, e sair da pista é cair. No Solo, contra o relógio e os fantasmas dos amigos.': 'Een race met wortelschepen op een zwevende baan, veel sneller dan de kart. Energie is je leven en je turbo: de rand raken kost energie, de roze strook laadt bij, en van de baan raken is vallen. Solo, tegen de klok en de geesten van je vrienden.',
  'Os karts numa arena fechada, cada um com três balões. Pegue as caixas e use os itens para estourar os balões dos outros: quem fica sem balão sai, e ganha quem sobrar.': 'De karts in een gesloten arena, elk met drie ballonnen. Pak de kisten en gebruik de items om de ballonnen van de anderen te laten knallen: wie geen ballonnen meer heeft, ligt eruit, en wie overblijft wint.',
  'Esquadrilha da toca': 'Eskader van het hol',
  'Aviõezinhos de cenoura contra a praga da horta: desvie das sementes, pegue os reforços e derrube o espantalho mecânico no fim. A turma voa as mesmas ondas, e a esquadrilha soma os pontos.': 'Wortelvliegtuigjes tegen de plagen in de moestuin: ontwijk de zaadjes, pak de versterkingen en haal aan het eind de mechanische vogelverschrikker neer. De groep vliegt dezelfde golven, en het eskader telt de punten op.',
