  'Minigolfe 3D': 'Minigolf 3D',
  'Oito buracos em 3D, com rampas, castelo e moinho, todos jogando o mesmo ao mesmo tempo. Arraste para mirar e dar a força, e solte. Ganha quem somar menos tacadas.': 'Acht holes in 3D, met hellingen, een kasteel en een molen, iedereen speelt tegelijk dezelfde. Sleep om te richten en kracht te geven, en laat los. Wie in totaal de minste slagen heeft, wint.',
  'Ver o buraco de cima': 'Hole van bovenaf bekijken',
  'Fora da pista! Mais uma tacada.': 'Van de baan! Eén slag erbij.',
  'Arraste para o lado para mirar e para baixo para a força, e solte. No teclado: as setas miram, e o Espaço segurado dá a força.': 'Sleep opzij om te richten en omlaag voor kracht, en laat los. Met het toetsenbord: de pijltjes richten, en de ingedrukte spatiebalk geeft de kracht.',
  'Futebol dos coelhos': 'Konijnenvoetbal',
  'Futebol de campo pequeno, visto de cima. Encoste na bola para conduzir, segure Espaço para chutar mais forte e passe com X. Na sala, os times se completam com robôs.': 'Voetbal op een klein veld, van bovenaf gezien. Raak de bal aan om te dribbelen, houd de spatiebalk ingedrukt om harder te schieten en passeer met X. In de kamer worden de teams aangevuld met bots.',
