  'Caça às pragas da horta': 'Plagenjacht in de moestuin',
  'Corvos e gafanhotos atacam a horta. Mire e clique para acertar antes que fujam: a munição é contada, e cada onda vem mais rápida. Ganha quem fizer mais pontos.': 'Kraaien en sprinkhanen vallen de moestuin aan. Richt en klik om ze te raken voordat ze ontsnappen: de munitie is beperkt, en elke golf komt sneller. Wie de meeste punten scoort, wint.',
  'Mire e clique nas pragas antes que fujam. Cada tiro gasta uma cenoura.': 'Richt en klik op de plagen voordat ze ontsnappen. Elk schot kost een wortel.',
