  'Os coelhos defendem a horta de raposas, corvos e um texugo. Andem juntos, batam em combo e cuidem uns dos outros: de 1 a 4 pessoas.': 'De konijnen verdedigen de moestuin tegen vossen, kraaien en een das. Loop samen op, sla in combo\'s en let op elkaar: 1 tot 4 mensen.',
  'Pulo do coelho': 'Konijnensprong',
  'Uma corrida de plataforma: correr, pular e não cair. Sozinho, contra o relógio e os fantasmas dos amigos; com a turma, ao vivo, numa fase ou nas três.': 'Een platformrace: rennen, springen en niet vallen. In je eentje tegen de klok en de geesten van je vrienden; met de groep live, in één level of alle drie.',
  'Troque dois legumes vizinhos para juntar três ou mais iguais. A pilha sobe sem parar: não deixe chegar ao topo. Com a turma, as cadeias e os combos mandam caixotes para os outros.': 'Wissel twee groenten naast elkaar om drie of meer gelijke te verzamelen. De stapel stijgt zonder te stoppen: laat hem de top niet bereiken. Met de groep sturen ketens en combo\'s kratten naar de anderen.',
  'Seis buracos de minigolfe, todos jogando o mesmo ao mesmo tempo. Puxe a bola para trás e solte para dar a tacada. Ganha quem somar menos tacadas.': 'Zes holes minigolf, iedereen speelt dezelfde tegelijk. Trek de bal naar achteren en laat los om te slaan. Wie in totaal de minste slagen heeft, wint.',
  'Cada um joga o dado na sua vez e anda pela horta. Junte cenouras para comprar a cenoura dourada, e depois de cada rodada a turma joga um microjogo. Ganha quem tiver mais cenouras douradas.': 'Iedereen gooit om de beurt de dobbelsteen en loopt door de moestuin. Verzamel wortels om de gouden wortel te kopen, en na elke ronde speelt de groep een minispel. Wie de meeste gouden wortels heeft, wint.',
  'Os pódios e as conquistas da turma': 'De podia en de prestaties van de groep',
