  'Até sobrar um': 'Tot er één over is',
  'Ande pelas capitais do Brasil, compre cidades e cobre aluguel de quem parar nelas. Com uma região inteira, dá para construir prédios. Troque, dispute nos leilões e não fique sem dinheiro.': 'Reis langs de hoofdsteden van Brazilië, koop steden en vraag huur aan wie erop stopt. Met een hele regio kun je gebouwen neerzetten. Ruil, bied op veilingen en zorg dat je geld niet opraakt.',
