  'Damas': 'Dammen',
  'Batalha naval': 'Zeeslag',
  'O dominó de sempre, de 2 a 4 pessoas (com 4, em duplas). Encaixe as pedras pelas pontas, e quem bater primeiro leva os pontos das mãos dos outros.': 'Het klassieke domino, voor 2 tot 4 mensen (met 4 in duo\'s). Leg de stenen aan de uiteinden aan; wie als eerste uit is, krijgt de punten uit de handen van de anderen.',
  'O truco paulista, com vira e manilha, em 2 ou em duplas de 4. Peça truco, aumente para seis, nove e doze, ou corra. Ganha quem fizer 12 pontos.': 'Truco uit São Paulo, met keerkaart en troeven, met 2 of met 4 in duo\'s. Roep truco, verhoog naar zes, negen en twaalf, of trek je terug. Wie 12 punten haalt, wint.',
  'As damas brasileiras: comer é obrigatório, para a frente e para trás, e a dama anda a diagonal inteira. A sala assiste.': 'Braziliaans dammen: slaan is verplicht, vooruit en achteruit, en de dam gaat over de hele diagonaal. De kamer kijkt mee.',
  'Cada um esconde a sua frota e atira no mar do outro. Acertou, atira de novo. Vence quem afundar a frota inteira primeiro. A sala assiste.': 'Iedereen verstopt de eigen vloot en schiet in de zee van de ander. Raak? Dan schiet je nog een keer. Wie als eerste de hele vloot laat zinken, wint. De kamer kijkt mee.',
