  'Pegue os ingredientes nos caixotes, pique na tábua, cozinhe no fogão e no forno sem queimar, monte no prato e entregue na janela. Todos recebem os mesmos pedidos: ganha quem entregar mais pratos em 3 minutos.': 'Pak de ingrediënten uit de kratten, snijd ze op de plank, bak ze op het fornuis en in de oven zonder ze te laten aanbranden, maak het bord op en geef het af bij het luik. Iedereen krijgt dezelfde bestellingen: wie in 3 minuten de meeste borden afgeeft, wint.',
