  // a Ponte da toca (06/11/2026)
  'Ponte da toca': 'Holbrug',
  'Trinta segundos para montar uma ponte de madeira e aço. Ganha quem levar o tráfego até o outro lado gastando menos.': 'Dertig seconden om een brug van hout en staal te bouwen. Wie het verkeer het goedkoopst naar de overkant krijgt, wint.',
  'Pista': 'Wegdek',
  'Aço': 'Staal',
  'Testar': 'Testen',
  'Montar': 'Bouwen',
  'Passou!': 'Gelukt!',
  '{n}% do caminho': '{n}% van de weg',
  'Gincana da toca': 'Holparcours',
  'Uma corrida de obstáculos em 3D: corra, pule e se equilibre por plataformas, esteiras, serras e varredores até a bandeira. Caiu, volta à última bandeira. No Solo, contra o relógio e os fantasmas dos amigos.': 'Een hindernisparcours in 3D: ren, spring en bewaar je evenwicht over platforms, lopende banden, zagen en zwaaiarmen tot aan de vlag. Val je eraf, dan ga je terug naar de laatste vlag. In Solo tegen de klok en de geesten van je vrienden.',
  'Quedas: {n}': 'Vallen: {n}',
  'Tocar o sino: todos os trabalhadores para dentro do centro da vila': 'Luid de klok: alle arbeiders het dorpscentrum in',
  'Tocar o sino de novo: todos de volta ao trabalho': 'Luid de klok nog eens: iedereen weer aan het werk',
  'Este lugar já está cheio.': 'Deze plek is al vol.',
  'Clássico': 'Klassiek',
  'Colorido': 'Kleurrijk',
  // Saúde do servidor: ações da Hetzner e diagnóstico do host
  "Diagnóstico do host": "Hostdiagnose",
  "Registros limitados de Docker, SSH, logind e kernel dos três boots mais recentes. Podem conter endereços IP.": "Beperkte logs van Docker, SSH, logind en de kernel van de drie meest recente opstarts. Kunnen IP-adressen bevatten.",
  "Atualizar diagnóstico": "Diagnose vernieuwen",
  "Ainda não há snapshot. Ele será coletado na próxima abertura do cofre.": "Nog geen momentopname. Die wordt verzameld bij de volgende keer dat de kluis wordt geopend.",
  "Coletado em {data}": "Verzameld op {data}",
  "Medido pela {nome}": "Gemeten door {nome}",
  "Os mesmos números do painel do provedor. Inclui o disco, que o servidor não mede sozinho.": "Dezelfde cijfers als in het dashboard van de provider. Inclusief de schijf, die de server niet zelf meet.",
  "Ações no servidor": "Acties op de server",
  "O histórico da Hetzner: ligar, desligar e reiniciar, pelo painel ou pela API. Uma queda sem ação aqui não foi comandada por esses caminhos.": "De geschiedenis bij Hetzner: aanzetten, uitzetten en herstarten, via het dashboard of de API. Een storing zonder actie hier is niet via die wegen veroorzaakt.",
  "Nenhuma ação registrada.": "Geen acties vastgelegd.",
