  'Desfocado': "Vervagen",
  'Apagado': "Wissen",
  'Desfoca, apaga ou troca o que aparece atrás de você. A imagem da câmera não sai do computador para isso.': "Vervaagt, wist of vervangt wat er achter je te zien is. Het camerabeeld verlaat daarvoor je computer niet.",
  // A transmissão personalizada (16/11/2026)
  'Nativa': "Oorspronkelijk",
  'Resolução': "Resolutie",
  'Quadros por segundo': "Beelden per seconde",
  'Para quando a escolha automática errar: a resolução e os quadros ficam os que você escolher, do começo ao fim da transmissão.': "Voor als de automatische keuze ernaast zit: de resolutie en de beelden blijven wat jij kiest, van begin tot eind van de uitzending.",
  // O Syden Broadcast (16/11/2026)
  'Os efeitos de voz e de câmera feitos no seu computador, sem enviar nada a um servidor.': "De stem- en camera-effecten die op je computer gebeuren, zonder iets naar een server te sturen.",
  // O Comando Cenoura (16/11/2026)
  'Comando Cenoura': "Wortelcommando",
  'Correr e atirar com a turma: o lança-cenouras mira em oito direções, a granada abre caminho e quem solta os coelhinhos presos ganha reforço. O dragão espera no fim: de 1 a 4 pessoas.': "Ren en schiet met de groep: de wortelschieter mikt in acht richtingen, de granaat maakt de weg vrij en wie de opgesloten konijntjes bevrijdt, krijgt versterking. De draak wacht aan het eind: 1 tot 4 mensen.",
  'Andar e mirar': "Lopen en mikken",
  'Granada': "Granaat",
  // A Masmorra da Toca (16/11/2026)
  'Masmorra da Toca': "De kerker van het hol",
  'Atravessem juntos a toca do rei-cogumelo: salas cheias de bichos, um baú com a cenoura que vai e volta, botões que pedem dois ao mesmo tempo e a porta trancada. De 1 a 4 pessoas.': "Trek samen door het hol van de paddenstoelenkoning: kamers vol beestjes, een kist met de wortel die heen en terug vliegt, knoppen die er twee tegelijk nodig hebben en de afgesloten deur. 1 tot 4 mensen.",
  // O Ringue da Toca (16/11/2026)
  'Ringue da Toca': "Holring",
  'Boxe de reflexo contra três adversários do computador. Leia o aviso de cada golpe, esquive ou defenda e bata na brecha. Bater quando a luva brilha enche a estrela do soco forte.': "Reflexboksen tegen drie computertegenstanders. Lees de aankondiging van elke stoot, ontwijk of blok, en sla in de opening. Sla je als de handschoen schittert, dan vult de ster van de harde stoot.",
  'Esquivar': "Ontwijken",
  'Abaixar e defender': "Bukken en blokken",
  'Socar': "Slaan",
  'Soco forte': "Harde stoot",
  'Aperte os socos para levantar!': "Druk op de stoten om op te staan!",
  'Lutas vencidas: {n}': "Gewonnen gevechten: {n}",
  'Nocaute!': "Knock-out!",
  // A Rota Estelar (16/11/2026)
  'Rota Estelar': "Sterrenroute",
  'Coelhos em naves pela superfície de um planeta e pelo espaço: atire, segure o tiro para travar a mira, gire para desviar dos tiros e escolha o caminho na bifurcação. A turma voa a mesma rota, e o chefe espera no fim.': "Konijnen in ruimteschepen over het oppervlak van een planeet en de ruimte in: schiet, houd het schieten ingedrukt om een doel vast te zetten, draai rond om schoten af te weren en kies een pad bij de splitsing. De groep vliegt dezelfde route, en de baas wacht aan het eind.",
  'Pirueta': "Draai",
  'Segure para travar a mira': "Houd ingedrukt om vast te zetten",
  // O Pinball da Horta (16/11/2026)
  'Pinball da Horta': "Moestuin-pinball",
  'Uma mesa de pinball na horta: segure a mola, rebata nos repolhos e derrube as três cenouras para acender a toca do coelho, que solta mais uma bola. Três bolas, e sacudir demais trava a mesa.': "Een pinballtafel in de moestuin: hou de veer vast, kaats tegen de kolen en gooi de drie wortels om zodat het konijnenhol oplicht en nog een bal vrijlaat. Drie ballen, en te veel schudden blokkeert de tafel.",
  'Palhetas': "Flippers",
  'Mola': "Veer",
