  // Lendas da Toca (16/11/2026)
  'Lendas da Toca': "Legendes van het Hol",
  'Um RPG de turnos curto: cada um controla um herói da turma. Escolham juntos, combinem ataques e vençam o dragão do castelo.': "Een korte beurtgebaseerde RPG: iedereen bestuurt een held van de groep. Kies samen, combineer aanvallen en versla de draak van het kasteel.",
