  // Bichos da Toca (16/11/2026)
  'Bichos da Toca': "Holbeestjes",
  'Ande pelo campo, faça amizade com os bichos do mato usando uma cenoura e monte uma equipe de até seis. Vença o desafio da casa azul e, na sala, lute com a equipe de um amigo.': "Zwerf door de velden, sluit met een wortel vriendschap met de beestjes in het hoge gras en stel een team van maximaal zes samen. Versla de uitdaging in het blauwe huis en vecht in de ruimte tegen het team van een vriend.",
