  "Duas equipes de dois. Os robôs completam os lugares que faltam.": "Twee teams van twee. Bots vullen de lege plekken aan.",
  "Gênero": "Geslacht",
  "Levadiça": "Ophaalbrug",
  'Nenhuma conversa ainda. Toque em alguém na lista de pessoas da comunidade e escolha "Enviar mensagem".': "Nog geen gesprekken. Tik op iemand in de personenlijst van de community en kies \"Bericht versturen\".",
  "Varia": "Wisselend",
  "Vitória de {nomes}": "Overwinning voor {nomes}",
  "Vocês derrubaram os dois centros da vila da outra equipe.": "Jullie hebben beide dorpscentra van het andere team vernietigd.",
  // Os mini-games e as insígnias (19/11/2026)
  "A cidade que ninguém compra vai a leilão. Hipotecar uma cidade dá dinheiro, mas ela não cobra aluguel.": "Een stad die niemand koopt, gaat naar een veiling. Een hypotheek op een stad levert geld op, maar dan int hij geen huur.",
  "A dica acende a peça que move. O problema com dica não pontua; na corrida, ela tira 10 segundos.": "De hint licht het stuk op dat zet. Een opgave met hint levert geen punten op; in de race kost hij 10 seconden.",
  "A manilha é o valor seguinte ao da vira e ganha de todas. Entre elas: ouros, espadas, copas e paus, o zap.": "De troef is de waarde na die van de keerkaart en wint van alles. Onderling: ruiten, schoppen, harten en klaveren, de zap.",
  "A última nave de cada volta sai.": "Het laatste schip van elke ronde ligt eruit.",
  "Abaixar": "Bukken",
  "Acertos em sequência: {n}": "Goed op rij: {n}",
  "Ande pelo dado e compre a capital onde parar. Quem para na cidade de outro paga aluguel.": "Ga vooruit met de dobbelsteen en koop de hoofdstad waar je landt. Wie op de stad van een ander landt, betaalt huur.",
  "Cada linha, coluna e bloco de 3 × 3 tem os números de 1 a 9, sem repetir.": "Elke rij, kolom en elk blok van 3 × 3 bevat de getallen 1 tot en met 9, zonder herhaling.",
  "Cada um recebe 3 cartas. Leva a mão quem ganhar 2 das 3 rodadas.": "Iedereen krijgt 3 kaarten. Wie 2 van de 3 slagen wint, pakt de hand.",
  "Campeonato": "Kampioenschap",
  "Com 11 pontos, a dupla vê as cartas e decide se joga a mão de onze. Vence quem chegar a 12.": "Met 11 punten ziet het duo de kaarten en beslist of het de hand van elf speelt. Wie 12 haalt, wint.",
  "Com a região inteira, construa até 4 prédios: o aluguel sobe a cada um.": "Met de hele regio bouw je tot 4 gebouwen: de huur stijgt met elk ervan.",
  "Com estrelas, o soco forte (★) gasta todas de uma vez e dói mais.": "Met sterren verbruikt de harde stoot (★) ze allemaal tegelijk en doet meer pijn.",
  "Dica": "Hint",
  "Dica: este problema não pontua": "Hint: deze opgave telt niet",
  "Dica: tira 10 segundos": "Hint: kost 10 seconden",
  "Eliminação": "Eliminatie",
  "Encoste uma pedra numa ponta da mesa com o mesmo número.": "Leg een steen met hetzelfde getal tegen een uiteinde op tafel.",
  "Escolha a casa e depois o número. O lápis anota só para você.": "Kies het vakje en daarna het getal. Het potlood noteert alleen voor jou.",
  "Esquive do golpe e soque logo depois: é o contra-ataque, e vale estrela.": "Ontwijk de stoot en sla meteen daarna: dat is de counter, en die levert een ster op.",
  "Fora da corrida na volta {n}.": "Uit de race in ronde {n}.",
  "Força das cartas": "Kracht van de kaarten",
  "Ganha o maior patrimônio no fim das rodadas, ou quem sobrar.": "Het grootste vermogen aan het eind van de rondes wint, of wie overblijft.",
  "Iniciante": "Beginner",
  "Mestre": "Meester",
  "Na sequência, cada acerto traz um problema mais difícil, e o primeiro erro acaba.": "In Reeks brengt elk goed antwoord een moeilijkere opgave, en de eerste fout maakt er een eind aan.",
  "O número pequeno no botão diz quantos ainda faltam.": "Het kleine getal op de knop zegt hoeveel er nog ontbreken.",
  "Os cinco traçados seguidos contra o computador, com pontos.": "De vijf circuits na elkaar tegen de computer, met punten.",
  "Peça truco e a mão vale 3. Quem responde aceita, corre ou aumenta para 6, 9 ou 12.": "Roep truco en de hand is 3 waard. Wie antwoordt, accepteert, trekt zich terug of verhoogt naar 6, 9 of 12.",
  "Quem bate fica sem pedras e leva os pontos das mãos dos outros. Trancado, leva quem tem menos pontos na mão.": "Wie uitgaat, heeft geen stenen meer en krijgt de punten uit de handen van de anderen. Zit het vast, dan krijgt wie de minste punten in de hand heeft ze.",
  "Sem pedra que sirva, compre. Sem nada para comprar, a vez passa.": "Past er geen steen, pak er een. Valt er niets meer te pakken, dan gaat de beurt over.",
  "Sequência": "Reeks",
  "Soque quando a luva brilhar: o golpe para e você ganha uma estrela.": "Sla als de handschoen schittert: de stoot stopt en je krijgt een ster.",
