  "Saara": "Sahara",
  "Sai um animal secreto, e cada um chuta outros. Cada chute mostra o que bate com o secreto: a classe, a dieta, onde ele vive e o peso. Quem acertar com menos chutes ganha mais pontos.": "Er wordt een geheim dier getrokken, en iedereen raadt andere. Elke gok laat zien wat overeenkomt met het geheime: de klasse, het dieet, waar het leeft en het gewicht. Wie het in minder gokken raadt, krijgt meer punten.",
  "Sai um dinossauro secreto, e cada um chuta outros. Cada chute mostra o que bate com o secreto: o período, a dieta, o grupo, o comprimento e onde ele foi achado. Quem acertar com menos chutes ganha mais pontos.": "Er wordt een geheime dinosaurus getrokken, en iedereen raadt andere. Elke gok laat zien wat overeenkomt met de geheime: de periode, het dieet, de groep, de lengte en waar hij gevonden is. Wie het in minder gokken raadt, krijgt meer punten.",
  "Sai um elemento químico secreto, e cada um chuta outros. Cada chute mostra o que bate com o secreto: a família, o estado físico, o período, o grupo e o número atômico. Quem acertar com menos chutes ganha mais pontos.": "Er wordt een geheim scheikundig element getrokken, en iedereen raadt andere. Elke gok laat zien wat overeenkomt met het geheime: de familie, de aggregatietoestand, de periode, de groep en het atoomnummer. Wie het in minder gokken raadt, krijgt meer punten.",
  "Sai um estado secreto do Brasil, e cada um chuta outros. Cada chute mostra a distância e a direção até o secreto, a região, a população, a área, o litoral e a fronteira com outro país. Quem acertar com menos chutes ganha mais pontos.": "Er wordt een geheime staat van Brazilië getrokken, en iedereen raadt andere. Elke gok laat de afstand en de richting naar de geheime zien, de regio, de bevolking, de oppervlakte, de kust en de grens met een ander land. Wie het in minder gokken raadt, krijgt meer punten.",
